export default async (): Promise<RequestMessage> => (
{
  // One request, N responses. The unary invoke rejects this method; the UI, the
  // CLI and the invoke_saved_streaming MCP tool all run it. Raise `count` past
  // the MCP frame cap and the tool result comes back `truncated`.
  message: "tick",
  count: Number(gv.request.params.count ?? 5),
}
)
